import React, { useEffect, useMemo, useState } from "react";
import { formatTime } from "./TimelineBar";

function clamp(x, a, b) {
  return Math.max(a, Math.min(b, x));
}

export default function Playhead({ duration, currentTime, scrollRef, contentRef }) {
  const [left, setLeft] = useState(0);

  const pct = useMemo(() => clamp(currentTime / (duration > 0 ? duration : 1), 0, 1), [currentTime, duration]);

  useEffect(() => {
    const outer = scrollRef.current;
    const inner = contentRef.current;
    if (!outer || !inner) return;

    const recompute = () => {
      const x = pct * inner.scrollWidth;
      setLeft(x - outer.scrollLeft);
    };

    recompute();
    outer.addEventListener("scroll", recompute, { passive: true });
    window.addEventListener("resize", recompute);
    return () => {
      outer.removeEventListener("scroll", recompute);
      window.removeEventListener("resize", recompute);
    };
  }, [pct, scrollRef, contentRef]);

  return (
    <div style={{ ...styles.wrap, left }}>
      <div style={styles.timeLabel}>{formatTime(currentTime)}</div>
      <div style={styles.line} />
      <div style={styles.dot} />
    </div>
  );
}

const styles = {
  wrap: {
    position: "absolute",
    top: 6,
    bottom: 6,
    width: 0,
    pointerEvents: "none",
    transform: "translateX(0px)",
  },
  line: {
    position: "absolute",
    top: 0,
    bottom: 0,
    width: 3,
    background: "rgba(255,255,255,0.95)",
    boxShadow: "0 0 0 1px rgba(0,0,0,0.35), 0 0 14px rgba(255,255,255,0.35)",
    borderRadius: 2,
  },
  dot: {
    position: "absolute",
    top: -2,
    left: -7,
    width: 16,
    height: 16,
    borderRadius: 999,
    background: "white",
    boxShadow: "0 8px 18px rgba(0,0,0,0.35)",
    border: "2px solid rgba(0,0,0,0.25)",
  },
  timeLabel: {
    position: "absolute",
    top: -34,
    left: -20,
    padding: "4px 8px",
    borderRadius: 999,
    background: "rgba(17,24,39,0.75)",
    border: "1px solid rgba(255,255,255,0.12)",
    color: "white",
    fontSize: 12,
    fontWeight: 900,
    fontVariantNumeric: "tabular-nums",
    backdropFilter: "blur(10px)",
    whiteSpace: "nowrap",
  },
};
